            try operands.append(alloc, trim_operand);
            trim_transferred = true;
        }
    }
    try parser.expectToken(tokens, pos, .rparen);

    return try lower_expr.buildFunctionExpressionFromOperandListAlloc(alloc, kind, &operands);
