            var lowered = parser_context.ParserState.ContextAccessors.parseRecursiveUpdateJoinedMutationSource(&parser_state) catch |err| switch (err) {
                error.InvalidRowsRequest => return error.UnsupportedSqlShape,
                else => return err,
