const TestPrimaryResolver = test_support.TestPrimaryResolver;

test "sql adapter lower dml validates generated child read payloads" {
    const alloc = std.testing.allocator;
    var parsed = try tokenized.ParsedSql.initAlloc(alloc, "SELECT id FROM usage_records");
    defer parsed.deinit(alloc);

    try validateGeneratedChildReadParsedSql(&parsed);

    if (parsed.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .read => |read| read.projection_tokens = read.source_tokens,
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;

    try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedChildReadParsedSql(&parsed));

    var insert_source = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id) SELECT id FROM usage_records WHERE status = 'ready'",
    );
    defer insert_source.deinit(alloc);
    switch (insert_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedDmlReadSourceBodyAlloc(alloc, &insert_source, dml),
        else => return error.TestUnexpectedResult,
    }
    if (insert_source.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    const projection_tokens = (dml.source_read orelse return error.TestUnexpectedResult).projection_tokens orelse return error.TestUnexpectedResult;
                    dml.source_read.?.where_tokens = projection_tokens;
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (insert_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedDmlReadSourceBodyAlloc(alloc, &insert_source, dml)),
        else => return error.TestUnexpectedResult,
    }

    var set_source = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id) SELECT id FROM usage_records UNION SELECT id FROM archived_records",
    );
    defer set_source.deinit(alloc);
    switch (set_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedDmlReadSourceBodyAlloc(alloc, &set_source, dml),
        else => return error.TestUnexpectedResult,
    }
    if (set_source.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    const projection_tokens = (dml.source_read orelse return error.TestUnexpectedResult).projection_tokens orelse return error.TestUnexpectedResult;
                    dml.source_read.?.set_operation_tokens = projection_tokens;
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (set_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedDmlReadSourceBodyAlloc(alloc, &set_source, dml)),
        else => return error.TestUnexpectedResult,
    }

    var span_source = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id) SELECT id FROM usage_records",
    );
    defer span_source.deinit(alloc);
    switch (span_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedDmlReadSourceBodyAlloc(alloc, &span_source, dml),
        else => return error.TestUnexpectedResult,
    }
    if (span_source.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| dml.source_read.?.command_span.start = 0,
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (span_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedDmlReadSourceBodyAlloc(alloc, &span_source, dml)),
        else => return error.TestUnexpectedResult,
    }

    var relation_source = try tokenized.ParsedSql.initAlloc(
        alloc,
        "UPDATE usage_records SET status = archived_records.status FROM archived_records WHERE usage_records.id = archived_records.id",
    );
    defer relation_source.deinit(alloc);
    switch (relation_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedDmlRelationSourceBody(&relation_source, dml),
        else => return error.TestUnexpectedResult,
    }
    if (relation_source.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| dml.source_read.?.statement_span.start = 0,
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (relation_source.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedDmlRelationSourceBody(&relation_source, dml)),
        else => return error.TestUnexpectedResult,
    }
}

test "sql adapter lower dml validates recursive generated CTE child reads" {
    const alloc = std.testing.allocator;
    var parsed = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE source_rows AS (SELECT id FROM usage_records) UPDATE usage_records SET status = 'done' WHERE id IN (SELECT id FROM source_rows)",
    );
    defer parsed.deinit(alloc);

    const generated_statement = parsed.generated_statement orelse return error.TestUnexpectedResult;
    const end = switch (generated_statement.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| generatedDmlStatementEnd(parsed.items(), dml.statement_span) orelse return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    };
    switch (generated_statement.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedRecursiveDmlCtePayloadAlloc(alloc, &parsed, dml, end),
        else => return error.TestUnexpectedResult,
    }

    var parsed_multi = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE seed_rows AS (SELECT id FROM usage_records), source_rows AS (SELECT id FROM seed_rows), final_rows AS (SELECT id FROM source_rows) UPDATE usage_records SET status = 'done' WHERE id IN (SELECT id FROM final_rows)",
    );
    defer parsed_multi.deinit(alloc);
    const multi_end = switch (parsed_multi.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| generatedDmlStatementEnd(parsed_multi.items(), dml.statement_span) orelse return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    };
    switch (parsed_multi.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedRecursiveDmlCtePayloadAlloc(alloc, &parsed_multi, dml, multi_end),
        else => return error.TestUnexpectedResult,
    }
    var parsed_multi_gap = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE seed_rows AS (SELECT id FROM usage_records), source_rows AS (SELECT id FROM seed_rows), final_rows AS (SELECT id FROM source_rows) UPDATE usage_records SET status = 'done' WHERE id IN (SELECT id FROM final_rows)",
    );
    defer parsed_multi_gap.deinit(alloc);
    const multi_gap_end = switch (parsed_multi_gap.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| generatedDmlStatementEnd(parsed_multi_gap.items(), dml.statement_span) orelse return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    };
    if (parsed_multi_gap.generated_statement) |*mutable_statement| {
        if (mutable_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    if (dml.cte_prefix) |*cte_prefix| {
                        try std.testing.expectEqual(@as(usize, 3), cte_prefix.items.len);
                        cte_prefix.items[1].name_tokens.start -= 1;
                    } else return error.TestUnexpectedResult;
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (parsed_multi_gap.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedRecursiveDmlCtePayloadAlloc(alloc, &parsed_multi_gap, dml, multi_gap_end)),
        else => return error.TestUnexpectedResult,
    }

    if (parsed_multi.generated_statement) |*mutable_statement| {
        if (mutable_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    if (dml.cte_prefix) |*cte_prefix| {
                        try std.testing.expectEqual(@as(usize, 3), cte_prefix.items.len);
                        const projection_tokens = cte_prefix.items[1].body_read.projection_tokens orelse return error.TestUnexpectedResult;
                        cte_prefix.items[1].body_tokens = projection_tokens;
                        cte_prefix.items[1].body_read.tokens = projection_tokens;
                        cte_prefix.items[1].body_read.source_tokens = null;
                    } else return error.TestUnexpectedResult;
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (parsed_multi.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedRecursiveDmlCtePayloadAlloc(alloc, &parsed_multi, dml, multi_end)),
        else => return error.TestUnexpectedResult,
    }

    if (parsed.generated_statement) |*mutable_statement| {
        if (mutable_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    if (dml.cte_prefix) |*cte_prefix| {
                        const projection_tokens = cte_prefix.first_body_read.projection_tokens orelse return error.TestUnexpectedResult;
                        cte_prefix.first_body_tokens = projection_tokens;
                        cte_prefix.first_body_read.tokens = projection_tokens;
                        cte_prefix.first_body_read.source_tokens = null;
                    } else return error.TestUnexpectedResult;
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;

    switch (parsed.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedRecursiveDmlCtePayloadAlloc(alloc, &parsed, dml, end)),
        else => return error.TestUnexpectedResult,
    }

    var parsed_where_body = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH RECURSIVE source_rows AS (SELECT id FROM usage_records WHERE status = 'ready') UPDATE usage_records SET status = 'done' WHERE id IN (SELECT id FROM source_rows)",
    );
    defer parsed_where_body.deinit(alloc);
    const where_body_end = switch (parsed_where_body.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| generatedDmlStatementEnd(parsed_where_body.items(), dml.statement_span) orelse return error.TestUnexpectedResult,
        else => return error.TestUnexpectedResult,
    };
    switch (parsed_where_body.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try validateGeneratedRecursiveDmlCtePayloadAlloc(alloc, &parsed_where_body, dml, where_body_end),
        else => return error.TestUnexpectedResult,
    }
    if (parsed_where_body.generated_statement) |*mutable_statement| {
        if (mutable_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| {
                    if (dml.cte_prefix) |*cte_prefix| {
                        const projection_tokens = cte_prefix.first_body_read.projection_tokens orelse return error.TestUnexpectedResult;
                        cte_prefix.first_body_read.where_tokens = projection_tokens;
                    } else return error.TestUnexpectedResult;
                },
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    switch (parsed_where_body.generated_statement.?.ast orelse return error.TestUnexpectedResult) {
        .dml => |dml| try std.testing.expectError(error.UnsupportedSqlShape, validateGeneratedRecursiveDmlCtePayloadAlloc(alloc, &parsed_where_body, dml, where_body_end)),
        else => return error.TestUnexpectedResult,
    }
}

test "sql adapter lower dml lowers generated DML AST through typed write plans" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"kind":{"type":"keyword"},"source_id":{"type":"keyword"},"status":{"type":"keyword"},"organization_id":{"type":"keyword"},"quantity":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForDmlTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);
    const source_schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"archive_id":{"type":"keyword"},"archive_status":{"type":"keyword"},"archive_quantity":{"type":"numeric"}},"required":["archive_id"],"additionalProperties":false}}},"primary_key":{"columns":["archive_id"]}}
    ;
    const source_schema = try runtimeSchemaFromJsonForDmlTestAlloc(alloc, source_schema_json);
    defer runtime_schema.freeSchema(alloc, source_schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"status\":\"active\",\"organization_id\":\"o1\",\"quantity\":1}", .version = 9 };
    const txn_id = [_]u8{ 0x40, 0x41, 0x42, 0x43, 0x44, 0x45, 0x46, 0x47, 0x48, 0x49, 0x4a, 0x4b, 0x4c, 0x4d, 0x4e, 0x4f };
    const claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-generated-dml",
        .txn_id = txn_id,
    };
    const options = plan_mod.LowerWritePlanOptions{
        .unique_resolver = resolver_ctx.resolver(),
        .row_claim = claim,
        .sync_level = .full_text,
    };

    const cases = [_][]const u8{
        "INSERT INTO usage_records (id, status, organization_id, quantity) VALUES ('u2', 'active', 'o1', 7) RETURNING id",
        "INSERT INTO usage_records (id, status, quantity) SELECT id, status, quantity FROM usage_records WHERE status = 'ready'",
        "UPDATE usage_records SET status = 'disabled' WHERE id = 'u1' RETURNING id",
        "UPDATE usage_records SET status = 'disabled' WHERE organization_id = 'o1' RETURNING id",
        "UPDATE usage_records SET status = 'archived' WHERE usage_records.id IN (SELECT archived_records.id FROM archived_records WHERE organization_id = 'o1') FOR UPDATE SKIP LOCKED RETURNING id",
        "UPDATE usage_records SET status = 'archived' WHERE usage_records.id IN (SELECT archived_records.organization_id FROM archived_records WHERE archived_records.status = usage_records.status) FOR UPDATE SKIP LOCKED RETURNING id",
        "UPDATE usage_records SET status = 'archived' WHERE usage_records.id IN (SELECT archived_records.organization_id FROM archived_records WHERE archived_records.organization_id = 'o1' AND archived_records.status = usage_records.status) FOR UPDATE SKIP LOCKED RETURNING id",
        "UPDATE usage_records SET status = 'archived' WHERE usage_records.id IN (SELECT archived_records.organization_id FROM archived_records WHERE lower(archived_records.status) = lower(usage_records.status)) FOR UPDATE SKIP LOCKED RETURNING id",
        "UPDATE usage_records SET status = 'archived' WHERE EXISTS (SELECT 1 FROM archived_records WHERE archived_records.organization_id = usage_records.id AND archived_records.status = 'archived') FOR UPDATE SKIP LOCKED RETURNING id",
        "UPDATE usage_records SET status = 'archived' WHERE EXISTS (SELECT archived_records.organization_id FROM archived_records WHERE archived_records.organization_id = usage_records.id AND lower(archived_records.status) = lower(usage_records.status)) FOR UPDATE SKIP LOCKED RETURNING id",
        "UPDATE usage_records SET status = 'archived' WHERE (usage_records.id, usage_records.status) IN (SELECT archived_records.organization_id, archived_records.status FROM archived_records) FOR UPDATE SKIP LOCKED RETURNING id",
        "DELETE FROM usage_records WHERE id = 'u1' RETURNING id",
        "DELETE FROM usage_records WHERE organization_id = 'o1' RETURNING id",
        "DELETE FROM usage_records WHERE usage_records.id IN (SELECT archived_records.id FROM archived_records WHERE status = 'archived') FOR UPDATE SKIP LOCKED RETURNING id",
        "DELETE FROM usage_records WHERE usage_records.id IN (SELECT archived_records.organization_id FROM archived_records WHERE archived_records.status = usage_records.status) FOR UPDATE SKIP LOCKED RETURNING id",
        "DELETE FROM usage_records WHERE usage_records.id IN (SELECT archived_records.organization_id FROM archived_records WHERE archived_records.organization_id = 'o1' AND archived_records.status = usage_records.status) FOR UPDATE SKIP LOCKED RETURNING id",
        "DELETE FROM usage_records WHERE usage_records.id IN (SELECT archived_records.organization_id FROM archived_records WHERE lower(archived_records.status) = lower(usage_records.status)) FOR UPDATE SKIP LOCKED RETURNING id",
        "DELETE FROM usage_records WHERE EXISTS (SELECT 1 FROM archived_records WHERE archived_records.organization_id = usage_records.id AND archived_records.status = 'archived') FOR UPDATE SKIP LOCKED RETURNING id",
        "DELETE FROM usage_records WHERE EXISTS (SELECT archived_records.organization_id FROM archived_records WHERE archived_records.organization_id = usage_records.id AND lower(archived_records.status) = lower(usage_records.status)) FOR UPDATE SKIP LOCKED RETURNING id",
        "TRUNCATE usage_records",
        "MERGE INTO usage_records USING usage_records AS source ON usage_records.id = source.id WHEN MATCHED THEN UPDATE SET status = source.status",
    };

    for (cases) |sql| {
        var legacy = try lowerWritePlanForDmlTestAlloc(alloc, sql, schema, &.{}, options);
        defer legacy.deinit(alloc);
        var generated = try lowerGeneratedDmlWritePlanForDmlTestAlloc(alloc, sql, schema, &.{}, options);
        defer generated.deinit(alloc);
        try std.testing.expectEqual(std.meta.activeTag(legacy), std.meta.activeTag(generated));
    }

    var malformed_generated_dml = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, organization_id, quantity) VALUES ('u2', 'active', 'o1', 7) RETURNING id",
    );
    defer malformed_generated_dml.deinit(alloc);
    if (malformed_generated_dml.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| dml.target_table_tokens = null,
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(
        error.UnsupportedSqlShape,
        lowerWritePlanParsedSqlForDmlTestAlloc(alloc, &malformed_generated_dml, schema, &.{}, options),
    );

    var malformed_command_span_dml = try tokenized.ParsedSql.initAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, organization_id, quantity) VALUES ('u2', 'active', 'o1', 7) RETURNING id",
    );
    defer malformed_command_span_dml.deinit(alloc);
    if (malformed_command_span_dml.generated_statement) |*generated_statement| {
        if (generated_statement.ast) |*generated_ast| {
            switch (generated_ast.*) {
                .dml => |*dml| dml.command_span.end += 1,
                else => return error.TestUnexpectedResult,
            }
        } else return error.TestUnexpectedResult;
    } else return error.TestUnexpectedResult;
    try std.testing.expectError(
        error.UnsupportedSqlShape,
        lowerWritePlanParsedSqlForDmlTestAlloc(alloc, &malformed_command_span_dml, schema, &.{}, options),
    );

    var malformed_cte_command_span_dml = try tokenized.ParsedSql.initAlloc(
        alloc,
        "WITH recent_usage AS (SELECT id FROM usage_records WHERE kind = 'order') UPDATE usage_records SET status = 'active' WHERE id = 'u1'",
    );
    defer malformed_cte_command_span_dml.deinit(alloc);
    if (malformed_cte_command_span_dml.generated_statement) |*generated_statement| {
