    try std.testing.expectEqual(db_mod.types.SyncLevel.full_text, generated_default_conflict.sync_level);
    try std.testing.expectEqual(db_mod.types.SyncLevel.full_text, generated_default_conflict.batch.req.sync_level);
    try std.testing.expectEqual(@as(u32, 0), generated_default_conflict.batch.inserted);
    try std.testing.expectEqual(@as(u32, 1), generated_default_conflict.batch.transformed);
    try std.testing.expectEqual(@as(usize, 1), generated_default_conflict.batch.returning_rows.len);
    try std.testing.expectEqualStrings("{\"id\":\"u_default\",\"status\":\"active\",\"quantity\":1}", generated_default_conflict.batch.returning_rows[0]);

    var generated_truncate = try lowerGeneratedDmlWritePlanForDmlTestAlloc(
        alloc,
        "TRUNCATE TABLE public.usage_records, usage_archive RESTART IDENTITY CASCADE",
        schema,
        &.{},
        options,
    );
    defer generated_truncate.deinit(alloc);
    switch (generated_truncate) {
        .truncate_source => |truncate_source| {
            try std.testing.expectEqualStrings("usage_records", truncate_source.table_name);
            try std.testing.expectEqual(@as(usize, 1), truncate_source.additional_table_names.len);
            try std.testing.expectEqualStrings("usage_archive", truncate_source.additional_table_names[0]);
            try std.testing.expect(truncate_source.restart_identity);
            try std.testing.expect(truncate_source.truncate_cascade);
            try std.testing.expectEqual(options.sync_level, truncate_source.sync_level);
            try std.testing.expect(truncate_source.mutation.req.source.row_claim != null);
        },
        else => return error.TestUnexpectedResult,
    }
}

test "sql adapter lower dml routes write sql through typed plan families" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"kind":{"type":"keyword"},"source_id":{"type":"keyword"},"status":{"type":"keyword"},"organization_id":{"type":"keyword"},"quantity":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForDmlTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);
    var resolver_ctx = TestPrimaryResolver{ .row_json = "{\"id\":\"u1\",\"status\":\"active\",\"organization_id\":\"o1\"}", .version = 9 };
    const txn_id = [_]u8{ 0x30, 0x31, 0x32, 0x33, 0x34, 0x35, 0x36, 0x37, 0x38, 0x39, 0x3a, 0x3b, 0x3c, 0x3d, 0x3e, 0x3f };
    const claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "sql-writer",
        .txn_id = txn_id,
    };
    const options = plan_mod.LowerWritePlanOptions{
        .unique_resolver = resolver_ctx.resolver(),
        .row_claim = claim,
        .sync_level = .full_text,
    };

    var insert_plan = try lowerWritePlanForDmlTestAlloc(
        alloc,
        "INSERT INTO usage_records (id, status, organization_id) VALUES ('u2', 'active', 'o1') RETURNING id",
