        alloc,
        "UPDATE usage_records SET tags = array_append(tags, 'new'), tags = array_remove(tags, 'old') WHERE id = $1 RETURNING tags, array_append(tags, 'tail') AS tags_preview, array_remove(tags, 'new') AS tags_without_new",
        schema,
