    try std.testing.expectEqual(db_mod.types.TransformOpType.set, computed.batch.transforms[0].operations[0].op);
    try std.testing.expectEqualStrings("tags", computed.batch.transforms[0].operations[0].path);
    try std.testing.expectEqualStrings("[\"active\",\"new\"]", computed.batch.transforms[0].operations[0].value_json.?);
    try std.testing.expectEqualStrings("{\"tags\":[\"active\",\"new\"]}", computed.batch.returning_rows[0]);

    try std.testing.expectError(error.InvalidSqlCatalog, lowerUpdateForTestAlloc(
        alloc,
        "UPDATE usage_records SET status = array_append(status, 'bad') WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
        resolver_ctx.resolver(),
    ));
    try std.testing.expectError(error.UnsupportedSqlShape, lowerUpdateForTestAlloc(
        alloc,
        "UPDATE usage_records SET tags = array_append(tags, 3) WHERE id = $1",
        schema,
        &.{.{ .string = "u1" }},
        resolver_ctx.resolver(),
    ));
}

