test "sql adapter lower dml lowers claimed delete mutation source" {
    const alloc = std.testing.allocator;
    const schema_json =
        \\{"version":1,"storage_mode":"relational","default_type":"row","enforce_types":true,"document_schemas":{"row":{"schema":{"type":"object","properties":{"id":{"type":"keyword"},"status":{"type":"keyword"},"enabled":{"type":"boolean"},"expires_at":{"type":"numeric"}},"required":["id"],"additionalProperties":false}}},"primary_key":{"columns":["id"]}}
    ;
    const schema = try runtimeSchemaFromJsonForDmlTestAlloc(alloc, schema_json);
    defer runtime_schema.freeSchema(alloc, schema);
    const txn_id = [_]u8{ 0x20, 0x21, 0x22, 0x23, 0x24, 0x25, 0x26, 0x27, 0x28, 0x29, 0x2a, 0x2b, 0x2c, 0x2d, 0x2e, 0x2f };
    const claim: db_mod.types.RowClaimRequest = .{
        .mode = .for_update,
        .owner_id = "cleanup",
        .txn_id = txn_id,
    };

    var lowered = try lowerDeleteMutationSourceForTestAlloc(
        alloc,
        "DELETE FROM usage_records WHERE status = 'expired' AND expires_at < $1 ORDER BY expires_at ASC LIMIT 10 RETURNING id, LOWER(status) AS status_key, expires_at + 1 AS next_expires_at",
        schema,
        &.{.{ .integer = 1000 }},
        claim,
    );
    defer lowered.deinit(alloc);

    try std.testing.expectEqualStrings("usage_records", lowered.table_name);
    try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.delete, lowered.mutation.req.kind);
    try std.testing.expectEqual(@as(usize, 2), lowered.mutation.req.source.predicates.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.mutation.req.source.order_by.len);
    try std.testing.expectEqual(@as(u32, 10), lowered.mutation.req.source.limit.?);
    try std.testing.expect(lowered.mutation.req.source.row_claim != null);
    try std.testing.expect(!lowered.mutation.req.source.row_claim.?.skip_locked);
    try std.testing.expectEqual(@as(usize, 0), lowered.mutation.req.operations.len);
    try std.testing.expectEqual(@as(usize, 1), lowered.mutation.req.returning.len);
    try std.testing.expectEqualStrings("id", lowered.mutation.req.returning[0]);
    try std.testing.expectEqual(@as(usize, 2), lowered.mutation.req.returning_expressions.len);
    try std.testing.expectEqualStrings("status_key", lowered.mutation.req.returning_expressions[0].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.lower, lowered.mutation.req.returning_expressions[0].expression.kind);
    try std.testing.expectEqualStrings("next_expires_at", lowered.mutation.req.returning_expressions[1].output);
    try std.testing.expectEqual(db_mod.types.RelationalRowsExpressionKind.add, lowered.mutation.req.returning_expressions[1].expression.kind);

    var alias_all_returning = try lowerDeleteMutationSourceForTestAlloc(
        alloc,
        "DELETE FROM usage_records AS u WHERE status = 'expired' FOR UPDATE RETURNING u.*",
        schema,
        &.{},
        claim,
    );
    defer alias_all_returning.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", alias_all_returning.table_name);
    try std.testing.expect(alias_all_returning.mutation.req.returning_all);
    try std.testing.expectEqual(@as(usize, 0), alias_all_returning.mutation.req.returning.len);

    var alias_qualified_fields = try lowerDeleteMutationSourceForTestAlloc(
        alloc,
        "DELETE FROM usage_records AS u WHERE status = 'expired' FOR UPDATE RETURNING u.id, u.status AS deleted_status",
        schema,
        &.{},
