    try std.testing.expectEqual(runtime_schema.RelationalCheckOp.is_null, boolean_unknown.mutation.req.source.predicates[0].op);
    try std.testing.expect(boolean_unknown.mutation.req.source.predicates[0].value_json == null);

    var table_wide = try lowerDeleteMutationSourceForTestAlloc(
        alloc,
        "DELETE FROM usage_records RETURNING id, LOWER(status) AS status_key",
        schema,
        &.{},
        claim,
    );
    defer table_wide.deinit(alloc);
    try std.testing.expectEqualStrings("usage_records", table_wide.table_name);
    try std.testing.expectEqual(db_mod.types.RelationalRowsMutationKind.delete, table_wide.mutation.req.kind);
    try std.testing.expectEqual(@as(usize, 0), table_wide.mutation.req.source.predicates.len);
